SELECT gen_random_uuid()::text, 'formula', '$f_{max} = \frac{1}{n\,t_{pd}}$', 'Ripple Counter Maximum Frequency', '$f_{max} = \frac{1}{n\,t_{pd}}$', '$\text{Hz}$', 'An asynchronous counter must settle through every stage before the next clock.', '[{"symbol":"$n$","meaning":"number of flip-flops","unit":null},{"symbol":"$t_{pd}$","meaning":"delay of one flip-flop","unit":"$\\text{ns}$"}]'::jsonb, 'A synchronous counter clocks all stages together, so its limit is set by one flip-flop plus its logic.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'counters and registers' AND s."active"), NULL, false, 'PENDING', now(), now()
