SELECT gen_random_uuid()::text, 'formula', '$T = \frac{N \cdot CPI}{f}$', 'Execution Time and MIPS', '$T = \frac{N \cdot CPI}{f},\qquad MIPS = \frac{f}{CPI \times 10^6}$', '$\text{s}$', 'How long a program takes on a processor.', '[{"symbol":"$N$","meaning":"instructions executed","unit":null},{"symbol":"$CPI$","meaning":"average clock cycles per instruction","unit":null},{"symbol":"$f$","meaning":"clock frequency","unit":"$\\text{Hz}$"}]'::jsonb, 'Higher MIPS is not always faster: CPI and the instructions needed differ between processors.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'microprocessor architecture' AND s."active"), NULL, false, 'PENDING', now(), now()
