SELECT gen_random_uuid()::text, 'formula', '$\Delta V = \frac{V_{ref}}{2^n}$', 'ADC and DAC Resolution', '$\Delta V = \frac{V_{ref}}{2^n};\qquad \text{DAC: } V_{out} = V_{ref}\frac{D}{2^n};\qquad \text{ADC: } D = \left\lfloor\frac{V_{in}}{V_{ref}}2^n\right\rfloor$', '$\text{V}$', 'The smallest voltage step a converter resolves.', '[{"symbol":"$V_{ref}$","meaning":"reference (full-scale) voltage","unit":"$\\text{V}$"},{"symbol":"$n$","meaning":"number of bits","unit":null},{"symbol":"$D$","meaning":"digital code","unit":null}]'::jsonb, 'An 8-bit ADC on 5 V: 19.5 mV per step. Some texts divide by 2ⁿ − 1, making full scale exactly V_ref.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'interfacing and i/o' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
