SELECT gen_random_uuid()::text, 'formula', '$\text{chars/s} = \frac{\text{baud}}{\text{bits per frame}}$', 'Serial Character Rate', '$\text{characters per second} = \frac{\text{baud}}{1 + d + p + s}$', NULL, 'How many characters a serial (UART) line carries, counting the start and stop bits.', '[{"symbol":"$d$","meaning":"data bits","unit":null},{"symbol":"$p$","meaning":"parity bits (0 or 1)","unit":null},{"symbol":"$s$","meaning":"stop bits","unit":null},{"symbol":"$\\text{baud}$","meaning":"bits per second on the line","unit":null}]'::jsonb, '9600 baud, 8N1 (10 bits a frame): 960 characters a second.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'interfacing and i/o' AND s."active"), NULL, true, 'PENDING', now(), now()
