SELECT gen_random_uuid()::text, 'formula', '$\text{RST } n \to 8n$', 'Interrupt Vector Addresses (8085)', '$\text{RST } n \to 8n;\quad \text{TRAP} \to 0024\text{H};\ \text{RST 5.5} \to 002C\text{H};\ \text{RST 6.5} \to 0034\text{H};\ \text{RST 7.5} \to 003C\text{H}$', NULL, 'Where the 8085 jumps for each interrupt.', '[{"symbol":"$n$","meaning":"restart number 0–7","unit":null}]'::jsonb, 'Priority: TRAP (non-maskable) > RST 7.5 > 6.5 > 5.5 > INTR. For the 8086 the vector table entry is at 4 × type.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'interrupts' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS'
