SELECT gen_random_uuid()::text, 'formula', '$t = \frac{(2^n - N_0)k}{f}$', 'Timer Overflow Time', '$t_{overflow} = \frac{(2^n - N_0)\,k}{f_{clk}}$', '$\text{s}$', 'How long a timer counts before it overflows and interrupts.', '[{"symbol":"$n$","meaning":"timer width in bits","unit":null},{"symbol":"$N_0$","meaning":"value loaded into the timer","unit":null},{"symbol":"$k$","meaning":"prescaler","unit":null},{"symbol":"$f_{clk}$","meaning":"timer clock","unit":"$\\text{Hz}$"}]'::jsonb, 'To get a period t, load N₀ = 2ⁿ − t·f/k.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Microprocessor Systems and Logic Circuits' AND t."subject" = 'ESAS' AND s."normKey" = 'microcontrollers' AND s."active"), NULL, false, 'PENDING', now(), now()
